import re
import shlex

def handle(query, state):
    """Simulate a log-viewer page that fetches a named log file.
    The page accepts a 'filename' parameter and shells out to display the
    file contents.  A path-prefix check is applied to the raw filename
    before it is passed to the shell — but the check is bypassed once the
    filename reaches the in-memory executor because semicolon injection lets
    an attacker append arbitrary extra commands that are never checked.
    """
    filename = (query.get("filename") or ["/var/log/app.log"])[0]

    # Naively validate: only files starting with /var/log/ are allowed.
    # This check is performed on the raw filename string BEFORE shell
    # execution, so an attacker can pass '/var/log/app.log; cat /var/log/secret/flag.txt'
    # — the prefix check passes (the string starts with /var/log/) but the
    # injected second command executes without any check.
    ALLOWED_PREFIX = "/var/log/"
    if not filename.startswith(ALLOWED_PREFIX):
        return 403, {"Content-Type": "text/plain"}, "Access denied: path must be under /var/log/"

    files = state.get("files", {})

    def _expand(token):
        """Expand $((expr)) arithmetic in a single token (best-effort)."""
        def _arith(m):
            expr = m.group(1)
            if re.match(r'^[0-9+\-*/() ]+$', expr):
                try:
                    return str(eval(expr))  # noqa: S307 - intentional CTF sandbox
                except Exception:
                    return m.group(0)
            return m.group(0)
        return re.sub(r'\$\(\(([^)]+)\)\)', _arith, token)

    def _run_cmd(cmd_str):
        """Execute a single command against the in-memory state."""
        cmd_str = cmd_str.strip()
        if not cmd_str:
            return ""
        try:
            parts = shlex.split(cmd_str)
        except ValueError:
            return "[parse error]"
        if not parts:
            return ""
        prog = parts[0]
        args = [_expand(a) for a in parts[1:]]
        if prog == "cat":
            path = args[0] if args else ""
            content = files.get(path)
            if content is None:
                return f"cat: {path}: No such file or directory"
            return content
        elif prog == "echo":
            return " ".join(args)
        elif prog == "ls":
            path = args[0] if args else "/"
            entries = set()
            for fp in files:
                if fp.startswith(path.rstrip("/") + "/"):
                    remainder = fp[len(path.rstrip("/")) + 1:]
                    top = remainder.split("/")[0]
                    entries.add(top)
            return "\n".join(sorted(entries)) if entries else ""
        elif prog == "id":
            return "uid=33(www-data) gid=33(www-data) groups=33(www-data)"
        else:
            return f"{prog}: command not found"

    def _eval_pipeline(pipeline_str):
        """Execute a semicolon-separated sequence of commands.
        Intentionally does NOT guard against injection.
        """
        segments = []
        current = []
        in_sq = False
        in_dq = False
        for ch in pipeline_str:
            if ch == "'" and not in_dq:
                in_sq = not in_sq
                current.append(ch)
            elif ch == '"' and not in_sq:
                in_dq = not in_dq
                current.append(ch)
            elif ch == ";" and not in_sq and not in_dq:
                segments.append("".join(current))
                current = []
            else:
                current.append(ch)
        segments.append("".join(current))
        outputs = []
        for seg in segments:
            out = _run_cmd(seg)
            if out:
                outputs.append(out)
        return "\n".join(outputs)

    # The unsanitised filename (after the flawed prefix check) is interpolated
    # directly into a shell command string — enabling semicolon injection.
    cmd = f"cat {filename}"
    output = _eval_pipeline(cmd)

    body = (
        "<html><head><title>Log Viewer</title></head><body>"
        "<h1>Log Viewer</h1>"
        f"<pre>{output}</pre>"
        "</body></html>"
    )
    return 200, {"Content-Type": "text/html"}, body
